-- Event ids are UUIDv7 generated by the database (ADR 0007), in the event table and in every column that holds one.
-- Ids handed out so far become fixed UUIDs: 0197a002-0000-7000-8000-<id>.
-- No foreign keys: events, seating plans and RSVPs belong to different modules.
ALTER TABLE event ALTER COLUMN id DROP IDENTITY;
ALTER TABLE event ALTER COLUMN id TYPE UUID
    USING ('0197a002-0000-7000-8000-' || lpad(id::text, 12, '0'))::uuid;
ALTER TABLE event ALTER COLUMN id SET DEFAULT uuidv7();

ALTER TABLE seating_plan ALTER COLUMN event_id TYPE UUID
    USING ('0197a002-0000-7000-8000-' || lpad(event_id::text, 12, '0'))::uuid;
ALTER TABLE rsvp ALTER COLUMN event_id TYPE UUID
    USING ('0197a002-0000-7000-8000-' || lpad(event_id::text, 12, '0'))::uuid;
